<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
require dirname(__DIR__).'/app/bootstrap.php';
$dir=$argv[1]??'';if($dir===''||!is_dir($dir)||is_link($dir))throw new RuntimeException('Укажите существующий приватный каталог резервных копий');
$root=realpath($dir);$public=realpath(cfg()['public_dir']??'/nonexistent');if($public!==false&&str_starts_with($root.'/',$public.'/'))throw new RuntimeException('Резервная копия должна быть вне сайта');
$target=$root.'/giftcards-db-'.gmdate('Ymd-His').'-'.bin2hex(random_bytes(3)).'.json';$out=fopen($target,'x');if(!$out)throw new RuntimeException('Не создан файл резервной копии');chmod($target,0600);
try{db()->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');db()->beginTransaction();$tables=array_column(query('SHOW TABLES')->fetchAll(PDO::FETCH_NUM),0);$tables=array_values(array_filter($tables,fn($t)=>preg_match('/^(pm|pg)_[a-z_]+$/D',$t)));fwrite($out,'{"format":"pina-full-backup-v2","created":'.json_encode(gmdate('c')).',"tables":{');foreach($tables as $n=>$table){if($n)fwrite($out,',');fwrite($out,json_encode($table).':{"create":'.json_encode(query('SHOW CREATE TABLE `'.$table.'`')->fetch(PDO::FETCH_NUM)[1],JSON_THROW_ON_ERROR).',"rows":[');$s=query('SELECT * FROM `'.$table.'`');$i=0;while($row=$s->fetch()){if($i++)fwrite($out,',');fwrite($out,json_encode($row,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));}fwrite($out,']}');}fwrite($out,'}}');db()->commit();fclose($out);$check=json_decode(file_get_contents($target),true,512,JSON_THROW_ON_ERROR);if(count($check['tables'])!==count($tables))throw new RuntimeException('Проверка копии не пройдена');echo $target."\n";}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if(is_resource($out))fclose($out);if(is_file($target))unlink($target);throw $e;}
// Keep the code-encryption key, approved signature and uploaded contracts with the DB snapshot.
