try{$manifest=[];$add=static function(string $source,string $name)use($zip,&$manifest):void{if(is_link($source)||!is_file($source)||!$zip->addFile($source,$name))throw new RuntimeException('Не удалось добавить файл в приватный архив');$manifest[$name]=hash_file('sha256',$source);};$add($target,'database.json');$add(getenv('PINA_CONFIG')?:dirname(__DIR__).'/app/config.php','private-config.php');$storage=cfg()['giftcards']['storage_path']??'';if($storage!==''&&is_dir($storage)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($storage,FilesystemIterator::SKIP_DOTS)) as $f)if($f->isFile()&&!$f->isLink())$add($f->getPathname(),'documents/'.substr($f->getPathname(),strlen(rtrim($storage,'/'))+1));}$zip->addFromString('manifest.json',json_encode($manifest,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT));if(!$zip->close())throw new RuntimeException('Не завершена запись приватного архива');chmod($archive,0600);$verify=new ZipArchive();if($verify->open($archive,ZipArchive::CHECKCONS)!==true)throw new RuntimeException('Архив не прошёл проверку');$verify->close();echo $archive."\n";}catch(Throwable $e){@$zip->close();if(is_file($archive))unlink($archive);throw $e;}
